/**
 * The typed failure bridge between recursive runs and catalog handlers.
 *
 * @since 0.1.0
 */
import * as Catalog from "../Catalog.js";
/**
 * Carries a child run's original typed failure across the catalog boundary.
 *
 * @private
 * @since 0.1.0
 */
export class ChildRunError extends Catalog.CallError {
    error;
    constructor(error) {
        super({ cause: error.code, message: `${error._tag}: ${error.message}`, name: "agent" });
        this.error = error;
    }
}

/**
 * The steering port: messages from outside the chain, drained at link
 * boundaries into author-call context.
 *
 * The port is shaped so the notifications package's durable queue slots
 * in as the production binding when the engine mounts; the in-memory
 * layer is the stand-in. Chains that provide no steering service run
 * unchanged and journal identically — the chain looks the service up
 * optionally (https://chain.smithers.sh/contract/).
 *
 * @since 0.1.0
 */
import * as Context from "effect/Context";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Ref from "effect/Ref";
import * as Schema from "effect/Schema";
import * as Effect_1 from "effect/Effect";
/**
 * A steering queue that cannot be admitted to or drained.
 *
 * @category errors
 * @since 0.1.0
 * @slop
 */
export class SteeringError extends Schema.TaggedError()("/chain/SteeringError", {
    code: Schema.Literal("steering_unavailable").pipe(Schema.withConstructorDefault(Effect.succeed("steering_unavailable"))),
    message: Schema.String
}) {
}
/**
 * The steering service tag.
 *
 * @category services
 * @since 0.1.0
 * @slop
 */
export class Steering extends Context.Service()("/chain/Steering") {
}
/**
 * Builds a steering port from an implementation.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const make = (implementation) => Steering.of(implementation);
const unavailable = (operation) => new SteeringError({ message: `${operation} is unavailable` });
/**
 * A steering port whose every operation fails as unavailable, with
 * per-operation overrides — the default a test starts from.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const makeNoop = (overrides = {}) => make({
    admit: Effect.fn("Steering.admit")(() => Effect.fail(unavailable("admit"))),
    drain: Effect.fn("Steering.drain")(() => Effect.fail(unavailable("drain"))),
    ...overrides
});
/**
 * The unavailable steering port as a layer.
 *
 * @category layers
 * @since 0.1.0
 * @slop
 */
export const layerNoop = (overrides = {}) => Layer.succeed(Steering)(makeNoop(overrides));
/**
 * An in-memory steering queue: `admit` appends, `drain` takes everything.
 *
 * @category layers
 * @since 0.1.0
 * @slop
 */
export const layerMemory = (initial = []) => {
    // Snapshot now, not when the lazy layer is later built: a caller may
    // mutate its seed after constructing the layer but before providing it.
    const snapshot = [...initial];
    return Layer.effect(Steering)(Effect_1.gen(function* () {
        const ref = yield* Ref.make(snapshot);
        return make({
            admit: Effect.fn("Steering.admit")((message) => Ref.update(ref, (queue) => [...queue, message])),
            drain: Effect.fn("Steering.drain")(() => Ref.getAndSet(ref, []))
        });
    }));
};

/**
 * Disposal and failure translation for QuickJS's pending-job result.
 *
 * @since 0.1.0
 */
import * as Effect from "effect/Effect";
import * as JsonBoundary from "../JsonBoundary.js";
import * as ScriptRunner from "../ScriptRunner.js";
/**
 * Disposes a pending-job result and translates its live error handle before
 * disposal when execution failed.
 *
 * @private
 * @since 0.1.0
 */
export const check = (jobs) => {
    if (jobs.error === undefined) {
        jobs.dispose();
        return Effect.void;
    }
    const dumped = jobs.error.context.dump(jobs.error);
    jobs.dispose();
    return Effect.fail(new ScriptRunner.ScriptFailure({
        code: "runtime",
        message: JsonBoundary.failureMessage(dumped)
    }));
};
